    /**
     * Tests getting all PaymentProviders.
     *
     * @return    Collection
     */
    public List<PaymentProvider> testGetAll() throws Throwable {
    LOGGER.info( "PaymentProviderTest:testGetAll() - Retrieving Collection of PaymentProviders:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PaymentProvider : " );
    List<PaymentProvider> collection  = null;

    try {
        // call the static get method on the PaymentProviderService
        collection = service.getAllPaymentProvider();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PaymentProvider currEntity  = null;
            Iterator<PaymentProvider> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPaymentProviderId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

